// ############################ ITEM LIST ######################
.structItem
{
	&.is-inactive
	{
		opacity: .7;
	}
}

.structItem-extraInfo
{
	&&.listInline--bullet
	{
		> li
		{
			margin-left: 4px;
		}
	}
}

.structItem-itemTagLine
{
	font-size: @xf-fontSizeSmaller;
	margin-top: @xf-paddingSmall;
}

.structItem-parts
{
	&--item
	{
		> li:nth-child(even)
		{
			color: inherit;
		}
	}
}

.structItem-cell.structItem-cell--itemMeta
{
	width: 210px;
}

.structItem-metaItem--rating
{
	font-size: @xf-fontSizeSmall;
}

.label
{
	&.label--smallest
	{
		&.label--aligner
		{
			vertical-align: middle;
		}
	}
}

@media (max-width: @xf-responsiveWide)
{
	.structItem-cell.structItem-cell--itemMeta
	{
		width: 190px;
		font-size: @xf-fontSizeSmaller;
	}
}

@media (max-width: @xf-responsiveMedium)
{
	.structItem-cell.structItem-cell--itemMeta
	{
		display: block;
		width: auto;
		float: left;
		padding-top: 0;
		padding-left: 0;
		padding-right: 0;
		color: @xf-textColorMuted;

		.pairs
		{
			display: inline;

			&:before,
			&:after
			{
				display: none;
			}

			> dt,
			> dd
			{
				display: inline;
				float: none;
				margin: 0;
			}
		}

		.structItem-metaItem
		{
			display: inline;
		}

		.ratingStarsRow
		{
			display: inline;

			.ratingStarsRow-text
			{
				display: none;
			}
		}

		/*
		.structItem-metaItem--lastUpdate > dt
		{
			display: none;
		}
		*/

		.structItem-metaItem + .structItem-metaItem:before
		{
			display: inline;
			content: "\20\00B7\20";
			color: @xf-textColorMuted;
		}
	}
}

// #################################### ITEM BODY / VIEW ########################

.block-body + .block-minorHeader
{
	border-top:none;
	margin-top: @xf-paddingLarge;
}

.block-row--itemIcon
{
	float:left;
	padding-right: @xf-blockPaddingH;
	padding-top: @xf-blockPaddingV;
	padding-bottom: @xf-blockPaddingV;
}

<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width || $xf.options.dbtechShopItemIconMaxDimensions.height">
.avatar
{
    &.avatar--itemIconDefault,
    &.avatar--itemIcon
    {
		&.avatar--xxs
		{
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width">
				width: {{ $xf.options.dbtechShopItemIconMaxDimensions.width * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.125) }}px !important;
			</xf:if>
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.height">
				height: {{ $xf.options.dbtechShopItemIconMaxDimensions.height * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.125) }}px !important;
			</xf:if>
		}

		&.avatar--xs
		{
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width">
				width: {{ $xf.options.dbtechShopItemIconMaxDimensions.width * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.17) }}px !important;
			</xf:if>
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.height">
				height: {{ $xf.options.dbtechShopItemIconMaxDimensions.height * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.17) }}px !important;
			</xf:if>
		}

		&.avatar--s
		{
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width">
				width: {{ $xf.options.dbtechShopItemIconMaxDimensions.width * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.25) }}px !important;
			</xf:if>
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.height">
				height: {{ $xf.options.dbtechShopItemIconMaxDimensions.height * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.25) }}px !important;
			</xf:if>
		}

		&.avatar--m
		{
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width">
				width: {{ $xf.options.dbtechShopItemIconMaxDimensions.width * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.5) }}px !important;
			</xf:if>
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.height">
				height: {{ $xf.options.dbtechShopItemIconMaxDimensions.height * ($xf.options.dbtechShopItemIconMaxDimensions.disableScaling ? 1 : 0.5) }}px !important;
			</xf:if>
		}

		&.avatar--l
		{
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.width">
				width: {$xf.options.dbtechShopItemIconMaxDimensions.width}px !important;
			</xf:if>
			<xf:if is="$xf.options.dbtechShopItemIconMaxDimensions.height">
				height: {$xf.options.dbtechShopItemIconMaxDimensions.height}px !important;
			</xf:if>
		}
    }
}
</xf:if>

.itemBody
{
	.itemBody--main
	{
		padding: @xf-blockPaddingV @xf-blockPaddingH;
	}

	.actionBar-set
	{
		margin-top: @xf-messagePadding;
		font-size: @xf-fontSizeSmall;
	}
}

@media (max-width: @xf-responsiveWide)
{
	.itemBody
	{
		display: block;
	}
}

.p-navgroup-link
{
	&.p-navgroup-link--dbtech-shop i:after
	{
		.m-faBase();
		display: inline-block;
		min-width: 1em;
		.m-faContent(@fa-var-shopping-basket, .88em);

		<xf:set var="$addOnId">ThemeHouse/UIX</xf:set>
		<xf:if is="{$xf.addOns.{$addOnId}}">
			<xf:macro template="uix_icons.less" name="content" arg-icon="shopping-cart" />
		</xf:if>
	}
}

.avatar.avatar--itemIconDefault
{
	color: @xf-textColorMuted !important;
	background: mix(@xf-textColorMuted, @xf-avatarBg, 25%) !important;
	text-align: center;

	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
	font-size: inherit;

	> span:before
	{
		.m-faBase();
		.m-faContent(@fa-var-cog);
		vertical-align: middle;
	}
}

.avatar--itemIcon
{
	border-radius: inherit;
}

.listRows
{
	display: flex;
	flex-wrap: wrap;

	&.inputChoices
	{
		> .inputChoices-choice
		{
			width: 50px;
			padding-left: 1.2em;
		}
	}
}

@keyframes reveal {
	from {
		transform: scale(0.001);
	}
	to {
		transform: scale(1);
	}
}

@keyframes slide {
	to {
		transform: translateX(1.5em);
	}
}

.item-loader {
	display: none;
	text-align: center;
}

.item-status
{
	display: none;
}

.item-ellipsis
{
	font-size: @xf-fontSizeLarger;
	position: relative;
	width: 4em;
	height: 1em;
	margin: @xf-paddingLarge auto;

	.item-ellipsis--dot
	{
		display: block;
		width: 1em;
		height: 1em;
		border-radius: @xf-borderRadiusLarge;
		background: @xf-textColor;
		position: absolute;
		animation-duration: 0.5s;
		animation-timing-function: ease;
		animation-iteration-count: infinite;

		&:nth-child(1) {
			left: 0;
			animation-name: reveal;
		}

		&:nth-child(2) {
			left: 0;
			animation-name: slide;
		}

		&:nth-child(3) {
			left: 1.5em;
			animation-name: slide;
		}

		&:nth-child(4) {
			left: 3em;
			animation-name: reveal;
			animation-direction: reverse;
		}
	}
}

.itemList-grid
{
	display: flex;
	flex-flow: row wrap;
	justify-content: flex-start;

	margin: @xf-paddingSmall;
}

.itemList-item-grid
{
	display: flex;
	flex-flow: column nowrap;

	width: 262px;
	max-width: 262px;
	margin: @xf-paddingLargest;

	position: relative;
	/*overflow: hidden;*/

	border: 1px solid @xf-borderColorLight;
	border-radius: @block-borderRadius-inner;

	&.is-highlighted,
	&.is-moderated
	{
		background: @xf-contentHighlightBg;
	}

	&.is-deleted
	{
		opacity: .7;

		.structItem-title
		{
			text-decoration: line-through;
		}
	}

	&.is-mod-selected
	{
		background: @xf-inlineModHighlightColor;
		opacity: 1;
	}

	&.node
	{
		.avatar
		{
			margin-left: auto;
			margin-right: auto;
			display: block;
		}

		.itemList-item-grid
		{
			&--icon {
				padding: @xf-paddingMedium;
			}

			&--clearfix
			{
				padding: 0 @xf-paddingLarge @xf-paddingSmall;
				margin-top: auto;

				&:after
				{
					content: "";
					display: table;
					clear: both;
				}
			}

			&--priceRatingInfo
			{
				&:after
				{
					margin: @xf-paddingSmall;
				}

				.rating
				{
					float:left;
				}

				.price
				{
					float:right;
				}
			}

			&--buyButton
			{
				&:after
				{
					margin: @xf-paddingSmall;
				}
			}

			&--updateInfo
			{
				padding: @xf-blockPaddingV @xf-paddingLarge;
				.xf-menuFooter();
				width:100%;

				.listInline--pairs
				{
					> li
					{
						&:first-child
						{
							float:left;
						}

						&:last-child
						{
							float:right;
						}

						.pairs
						{
							> dt
							{
								color: @xf-textColor;
								font-weight: @xf-fontWeightHeavy;
							}
						}
					}
				}
			}
		}
	}
}

@media (max-width: @xf-responsiveMedium)
{
	.itemList-item-grid
	{
		&.node
		{
			> .node-body
			{
				.node-description
				{
					display: block;
				}
			}
		}
	}
}

.itemList-item-gridOverlayTop
{
	cursor: pointer;

	position: absolute;
	top: 3px;
	left: 3px;
	z-index: @zIndex-2;

	width: 25px;
	height: 25px;
	border-radius: @xf-borderRadiusMedium;

	background: @xf-overlayMaskColor;

	display: flex;
	align-items: center;
	justify-content: center;

	opacity: 0;

	.has-touchevents &,
	.itemList-item-grid:hover &
	{
		opacity: 1;
	}

	.itemList-item-grid.is-mod-selected &
	{
		opacity: 1;
		background: @xf-inlineModHighlightColor;

		&.iconic
		{
			> input
			{
				+ i:before
				{
					color: @xf-textColorDimmed;
				}

				&:hover
				{
					+ i:before
					{
						color: @xf-textColorDimmed;
					}
				}
			}
		}
	}

	&&.iconic
	{
		> input
		{
			+ i:before
			{
				color: @xf-contentBg;
				display: inline;
				vertical-align: -0.05em;
			}

			&:hover
			{
				+ i:before
				{
					color: xf-intensify(@xf-contentBg, 15%);
				}
			}
		}
	}
}

.formRow.formRow--permissionQuickSet
{
	> dt,
	> dd
	{
		padding-bottom: 0;
	}
}

.permissionChoices
{
	.m-listPlain();
	.m-clearFix();

	> li
	{
		float: left;
		margin-left: 1em;

		&:first-child
		{
			margin-left: 0;
		}
	}
}

.permissionChoices-choice
{
	border: 1px solid transparent;
	border-radius: @xf-borderRadiusMedium;

	&.is-selected
	{
		box-shadow: 1px 1px 5px rgba(0,0,0, .25);

		&.permissionChoices-choice--inherit
		{
			border-color: #c0c0c0;
			background: #ededed;
			color: #3c3c3c;
		}

		&.permissionChoices-choice--yes
		{
			border-color: #82ce85;
			background: #daf3d8;
			color: #3d793f;
		}

		&.permissionChoices-choice--no
		{
			border-color: #ecb25e;
			background: #fdf0cf;
			color: #9a6e30;
		}

		&.permissionChoices-choice--never
		{
			border-color: #eaa4a1;
			background: #fde9e9;
			color: #c84448;
		}
	}
}

.permissionChoices--flag
{
	label
	{
		display: block;
		min-width: 90px;
		text-align: center;
		padding: 0 @xf-paddingMedium;
	}

	.iconic i
	{
		position: relative;
		vertical-align: top;
	}
}

.permissionChoices--int
{
	.permissionChoices-choice--yes,
	.permissionChoices-choice--inherit
	{
		label
		{
			display: inline-block;
			line-height: 27px;
			padding: 0 @xf-paddingMedium;
			min-width: 90px;
			text-align: center;
		}

		.iconic i
		{
			position: relative;
			vertical-align: top;
		}
	}

	.inputGroup.inputGroup--joined
	{
		position: relative;

		.inputGroup-text
		{
			&.inputNumber-button
			{
				&.inputNumber-button--up
				{
					border-left: 0;
				}
			}
		}

		.input--number
		{
			display: inline;
			width: 80px;
			padding-top: @xf-paddingSmall;
			padding-bottom: @xf-paddingSmall;
		}
	}

	.permissionChoices-choice--int
	{
		&.is-disabled .inputGroup-text
		{
			.xf-inputDisabled(background);
		}

		&.is-disabled .permissionChoices-choiceIntLabel
		{
			display: block;
		}

		&.is-selected .input[type=number],
		&.is-selected .input[type=tel]
		{
			.xf-inputFocus();
		}
	}
